SELECT u.uid, b.name, haversine_km(6.7569, 125.3469, b.centroid_lat, b.centroid_lng) AS dist_km FROM users u JOIN barangays b ON b.name = u.barangay WHERE u.role = 'responder' AND u.is_approved = true AND u.responder_status = 'available' AND ST_DWithin(ST_SetSRID(ST_MakePoint(b.centroid_lng, b.centroid_lat), 4326)::geography, (SELECT location FROM incidents WHERE description = 'TEST-debug'), 3000);